// XIAO ESP32-C3 太阳能 + 18650 供电 —— 按电量 + 白天/夜晚动态调度
// 电量充足时持续运行（可放你的其他任务）；电量低于阈值进入 deep sleep，按情况决定睡多久。
//
// 接线：GPIO4(A2) 电池分压 1M/1M；GPIO3(A1) 传感器 AOUT；GPIO5(D3) -> 2N7000 栅极

#include <WiFi.h>
#include <time.h>
#include "esp_sleep.h"

const char* WIFI_SSID = "your_ssid";
const char* WIFI_PASS = "your_password";

#define PIN_BAT      4
#define PIN_SOIL     3
#define PIN_SENS_EN  5

// ---------- 电压阈值（mV），按你的电芯实测后微调 ----------
const int V_RUN_ENTER = 3900;  // 静置约 60%：达到这个才恢复持续运行（回差，避免反复启停）
const int V_RUN_EXIT  = 3650;  // 运行中（带负载）约 25%：低于这个就去睡
const int V_CRITICAL  = 3500;  // 静置约 5%：只睡觉，连 Wi-Fi 都不开

// ---------- 白天时段（本地时间） ----------
const int DAY_START = 8;
const int DAY_END   = 17;

// ---------- 各种情况的睡眠时长（分钟） ----------
const uint32_t SLEEP_DAY_LOW       = 20;   // 白天、电量不足：勤醒，看看充上来没有
const uint32_t SLEEP_NIGHT_LOW     = 120;  // 夜里、电量不足：低频上报
const uint32_t SLEEP_DAY_CRITICAL  = 60;   // 白天、电量极低：不联网，等太阳
// 夜里、电量极低：直接睡到 DAY_START + 2 小时

const uint32_t RUN_CHECK_MS = 60 * 1000;   // 持续运行时每分钟检查一次电量并上报

RTC_DATA_ATTR int lastRestMv = 0;          // 上次唤醒时的静置电压，deep sleep 后保留

// ===================== 测量 =====================
int readBatMv() {
  uint32_t sum = 0;
  for (int i = 0; i < 16; i++) { sum += analogReadMilliVolts(PIN_BAT); delay(2); }
  return (sum / 16) * 2;                   // 1M/1M 分压，乘 2 还原
}

int readSoilMv() {
  digitalWrite(PIN_SENS_EN, HIGH);         // 打开 2N7000，给传感器通电
  delay(200);                              // 等传感器稳定
  uint32_t sum = 0;
  for (int i = 0; i < 16; i++) { sum += analogReadMilliVolts(PIN_SOIL); delay(2); }
  digitalWrite(PIN_SENS_EN, LOW);
  return sum / 16;                         // 越干电压越高，需自行标定干/湿两点
}

// ===================== 时间 / 白天判断 =====================
int currentHour() {                        // 没对过时返回 -1
  struct tm t;
  if (!getLocalTime(&t, 10)) return -1;
  return t.tm_hour;
}

uint32_t minutesUntilHour(int hour) {
  struct tm t;
  if (!getLocalTime(&t, 10)) return 60;    // 断电重启后不知道时间：保守地 1 小时后再看
  int now = t.tm_hour * 60 + t.tm_min;
  int d = hour * 60 - now;
  if (d <= 0) d += 24 * 60;
  return d;
}

// 白天 = 在白天时段内，或者电压比上次高（说明正在被太阳充电）
bool isDaytime(int restMv) {
  bool charging = (lastRestMv > 0) && (restMv > lastRestMv + 20);
  int h = currentHour();
  if (h < 0) return charging;
  return (h >= DAY_START && h < DAY_END) || charging;
}

// ===================== 网络 =====================
bool connectWiFi(uint32_t timeoutMs = 10000) {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  uint32_t t0 = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - t0 < timeoutMs) delay(100);
  if (WiFi.status() != WL_CONNECTED) return false;
  configTzTime("CST-8", "ntp.aliyun.com", "pool.ntp.org");   // 北京时间
  struct tm t;
  getLocalTime(&t, 3000);
  return true;
}

void report(int soilMv, int batMv, const char* mode) {
  // TODO: 换成你的 MQTT / HTTP 上报
  Serial.printf("[%s] soil=%dmV bat=%dmV\n", mode, soilMv, batMv);
}

// ===================== 睡眠 =====================
void goSleep(uint32_t minutes) {
  digitalWrite(PIN_SENS_EN, LOW);
  WiFi.disconnect(true);
  WiFi.mode(WIFI_OFF);
  Serial.printf("sleep %u min\n", minutes);
  Serial.flush();
  esp_sleep_enable_timer_wakeup((uint64_t)minutes * 60ULL * 1000000ULL);
  esp_deep_sleep_start();
}

uint32_t decideSleep(int restMv, bool day) {
  if (restMv < V_CRITICAL) return day ? SLEEP_DAY_CRITICAL : minutesUntilHour(DAY_START + 2);
  return day ? SLEEP_DAY_LOW : SLEEP_NIGHT_LOW;
}

// ===================== 主流程 =====================
void setup() {
  pinMode(PIN_SENS_EN, OUTPUT);
  digitalWrite(PIN_SENS_EN, LOW);
  Serial.begin(115200);
  setCpuFrequencyMhz(80);                  // 降频省电，Wi-Fi 照常可用

  int restMv = readBatMv();                // 刚醒、还没开 Wi-Fi，最接近静置电压
  bool day = isDaytime(restMv);

  // 1) 电量极低：不联网，直接睡
  if (restMv < V_CRITICAL) {
    lastRestMv = restMv;
    goSleep(decideSleep(restMv, day));
  }

  // 2) 联网、对时、上报一次
  connectWiFi();
  day = isDaytime(restMv);                 // 对时后再判断一次
  report(readSoilMv(), restMv, "wake");

  // 3) 电量没回到恢复线：继续睡（回差）
  if (restMv < V_RUN_ENTER) {
    lastRestMv = restMv;
    goSleep(decideSleep(restMv, day));
  }

  // 4) 电量充足：进入 loop() 持续运行
  lastRestMv = 0;                          // 运行中的带载电压不能和静置电压比较
}

uint32_t lastCheck = 0;

void loop() {
  // ========== 在这里放你的其他任务（不要长时间阻塞） ==========


  // ========== 定时检查电量 ==========
  if (millis() - lastCheck >= RUN_CHECK_MS) {
    lastCheck = millis();
    if (WiFi.status() != WL_CONNECTED) connectWiFi(5000);
    int loadMv = readBatMv();              // 带负载电压，会比静置低 0.05–0.1V
    report(readSoilMv(), loadMv, "run");
    if (loadMv < V_RUN_EXIT) {
      goSleep(decideSleep(loadMv, isDaytime(loadMv)));
    }
  }
}

